class Solution { public: bool isAlienSorted(vector<string>& words,string order){int rank[26];for(int i=0;i<26;++i)rank[order[i]-'a']=i;for(int w=1;w<(int)words.size();++w){string& a=words[w-1];string& b=words[w];int i=0;while(i<(int)a.size()&&i<(int)b.size()&&a[i]==b[i])++i;if(i==(int)b.size()&&i<(int)a.size())return false;if(i<(int)a.size()&&i<(int)b.size()&&rank[a[i]-'a']>rank[b[i]-'a'])return false;}return true;} };
